local module = {}
module.Injection = nil
module.WuKongProvider = nil

-- 存储模型、全局变量和引用的表
local _models, _globals, _ref = {}, {}, {}

function module.new(moduleScript)
	if module.Injection then
		module.Injection(moduleScript)
	end

	local self = require(moduleScript)
	local name = moduleScript.Name

	-- 创建元表
	local mt = {
		_events = {},
		_getEvent = function(self, eventName)
			self._events[eventName] = self._events[eventName] or Instance.new("BindableEvent")
			return self._events[eventName]
		end,
		_fire = function(self, path, value, old)
			local event = self._events[path]
			if event then
				event:Fire(value, old)
			end
		end,
	}

	-- 复制非下划线开头的module方法到元表
	for i, v in pairs(module) do
		if not i:match("^_") then
			mt[i] = v
		end
	end

	-- 复制函数到元表
	for i, v in pairs(self) do
		if type(v) == "function" then
			mt[i] = v
		end
	end

	-- 深度处理表
	local function deep(t)
		if type(t) == "table" then
			_models[t] = {}
			for i, v in pairs(t) do
				_models[t][i] = v
				t[i] = nil
			end
			setmetatable(t, {
				__index = function(t, k)
					return mt[k] or _models[t][k]
				end,
				__newindex = function(t, k, v)
					local old = _models[t][k]
					_models[t][k] = v
					if old ~= v then
						mt:_fire(k, v, old)
					end
				end,
			})
		end
		return _models[t]
	end

	local global = self._global
	deep(self)
	if global then
		_globals[name] = self
	end

	module._setWuKongBinding(self)

	return self
end

function module:_setWuKongBinding()
	local wukong = module.WuKongProvider and module.WuKongProvider()
	if not wukong then
		return
	end
	for i, v in pairs(self:GetData()) do
		if typeof(v) == "string" and string.find(v, "/") == 1 then
			local isQuery = string.find(v, "?")
			if isQuery then
				if string.find(v, ",") then
					local paths = string.split(v, ",")
					local query = table.remove(paths, 1)
					local args = paths

					local querys = string.split(query, "?")
					local path = querys[1]

					local has, container = wukong:TryGetChild(path)
					if has then
						-- 注册观察者
						wukong:RegisterContainerPropertyObserver(path, function(container, propertyName)
							self[i] = wukong:ExecuteQuery(query, table.unpack(args))
						end)

						wukong:RegisterContainerPluginDataObserver(path, function(container, pluginName, pluginData)
							self[i] = wukong:ExecuteQuery(query, table.unpack(args))
						end)
						self[i] = wukong:ExecuteQuery(query, table.unpack(args))
					else
						warn(`[ Neza ] ${path} not found container`)
					end
				end
			else
				-- 查询字符串中的斜杠数量
				local slashCount = v:gsub("/", ""):len()
				if slashCount > 1 then
					local path = v
					pcall(function()
						local has, container = wukong:TryGetChild(path)
						if has then
							local count = container._element and container._element._count or 0
							self[i] = count
							-- 注册观察者
							wukong:RegisterContainerPropertyObserver(path, function(container, propertyName)
								if propertyName == "Element.Count" then
									local count = container._element and container._element._count or 0
									self[i] = count
								end
							end)
						else
							warn(`[ Neza ] ${path} not found container`)
						end
					end)
				end
			end
		end
	end
end

function module:_getGlobal(name)
	return _globals[name]
end

function module:GetData()
	return _models[self]
end

function module:Notify(path)
	local value = self[path]
	self:_fire(path, value)
end

function module:Set(path, value)
	local old = _models[self][path]
	_models[self][path] = value
	self:_fire(path, value, old)
end

return module
